+{
+  "_comment": "packages/mcp-server had no rule at all and classified as unknown_runtime_surface, so the package deciding what an AI client may reach in a project was governed by the default unknown-file policy and never required its own protocol evidence. 'high' confidence is what pins it: an unknown file forces confidence to low.",
+  "files": ["packages/mcp-server/src/mcp/server.ts", "packages/mcp-server/src/grant/scopes.ts"],
+  "expected": {
+    "lane": "L4",
+    "confidence": "high",
+    "impactsInclude": ["security", "privacy"],
+    "impactsExclude": ["unknown_runtime_surface"],
+    "evidenceInclude": ["unit", "mcp_protocol", "protected_l4_approval"]
+  }
+}

@@ -0,0 +1,10 @@
+{
+  "_comment": "The privacy claim 'nothing leaves your device' was an absolute with no instrument behind it (conflict DRIFT-PRIVACY-TRANSPORT-ABSOLUTE, evidence-insufficient, high). Now that browser_network_observation exists, a change to the code that would carry data off the device has to run it. A claim only checked when someone remembers is a claim, not a control.",
+  "files": ["packages/telemetry/src/redact-sensitive-fields.ts"],
+  "expected": {
+    "confidence": "high",
+    "impactsInclude": ["privacy", "security"],
+    "impactsExclude": ["unknown_runtime_surface"],
+    "evidenceInclude": ["unit", "browser_network_observation"]
+  }
+}

