+  constructor(init: ArqMcpErrorInit) {
+    super(init.message);
+    this.name = 'ArqMcpError';
+    this.code = init.code;
+    this.state = init.state;
+    this.retry = init.retry;
+    this.nextAction = init.nextAction;
+    this.warnings = init.warnings ?? [];
