+  const clock = createControlledClock(START);
+  const { host, operator } = createMemoryArqHost();
+  const audit = createAuditTrail(clock.now);
+  const bridge = new ArqBridge({
+    host,
+    registry: createDefaultDomainProfileRegistry(),
+    clock: clock.now,
