+        operationId: 'seed-1',
+        operationType: 'architecture.level.create',
+        operationVersion: '1.0.0',
+        arguments: { levelId: 'level-0', name: 'Ground', elevationMm: 0 },
+        preconditions: [],
+      },
+    ],
+    'operator',
+  );
+
+  const grant =
+    options.grant ??
+    createGrant({
+      grantId: 'grant-1',
+      subjectId: 'subject-1',
