+export function jsonValue(description?: string): Validator<JsonValue> {
+  return {
+    jsonSchema: withDescription({}, description),
+    validate(value, path = '$') {
+      if (!isJsonValue(value)) {
+        return fail(
+          path,
+          SCHEMA_ISSUE_CODES.type,
